let totalLen = 0;
for (const p of patterns) totalLen += p.length;
const maxStates = totalLen + 1;
const go = new Int32Array(maxStates * 26).fill(-1);
const cnt = new Int32Array(maxStates);
let states = 1;
for (const p of patterns) {
  let s = 0;
  for (let i = 0; i < p.length; i++) {
    const c = p.charCodeAt(i) - 97;
    if (go[s * 26 + c] === -1) go[s * 26 + c] = states++;
    s = go[s * 26 + c];
  }
  cnt[s]++;
}
const fail = new Int32Array(states);
const queue = [];
for (let c = 0; c < 26; c++) {
  const v = go[c];
  if (v === -1) go[c] = 0;
  else queue.push(v);
}
for (let h = 0; h < queue.length; h++) {
  const u = queue[h];
  cnt[u] += cnt[fail[u]];
  for (let c = 0; c < 26; c++) {
    const v = go[u * 26 + c];
    if (v === -1) go[u * 26 + c] = go[fail[u] * 26 + c];
    else { fail[v] = go[fail[u] * 26 + c]; queue.push(v); }
  }
}
