solutions.java:
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int k = Integer.parseInt(st.nextToken());
        String[] patterns = new String[k];
        int totalLen = 0;
        for (int i = 0; i < k; i++) {
            patterns[i] = br.readLine().trim();
            totalLen += patterns[i].length();
        }
        String text = br.readLine().trim();
        int maxStates = totalLen + 1;
        int[][] go = new int[maxStates][26];
        for (int[] row : go) Arrays.fill(row, -1);
        int[] cnt = new int[maxStates];
        int states = 1;
        for (String p : patterns) {
            int s = 0;
            for (int i = 0; i < p.length(); i++) {
                int c = p.charAt(i) - 'a';
                if (go[s][c] == -1) go[s][c] = states++;
                s = go[s][c];
            }
            cnt[s]++;
        }
        int[] fail = new int[states];
        int[] queue = new int[states];
        int head = 0, tail = 0;
        for (int c = 0; c < 26; c++) {
            int v = go[0][c];
            if (v == -1) go[0][c] = 0;
            else queue[tail++] = v;
        }
        while (head < tail) {
            int u = queue[head++];
            cnt[u] += cnt[fail[u]];
            for (int c = 0; c < 26; c++) {
                int v = go[u][c];
                if (v == -1) go[u][c] = go[fail[u]][c];
                else { fail[v] = go[fail[u]][c]; queue[tail++] = v; }
            }
        }
        int state = 0;
        long total = 0;
        for (int i = 0; i < text.length(); i++) {
            state = go[state][text.charAt(i) - 'a'];
            total += cnt[state];
        }
        System.out.println(total);
    }
}

