#include <bits/stdc++.h>
using namespace std;
int main() {
    int k;
    cin >> k;
    vector<string> patterns(k);
    for (auto &p : patterns) cin >> p;
    string text;
    cin >> text;
    vector<array<int, 26>> go(1);
    go[0].fill(-1);
    vector<int> cnt(1, 0);
    for (auto &p : patterns) {
        int s = 0;
        for (char ch : p) {
            int c = ch - 'a';
            if (go[s][c] == -1) {
                go[s][c] = go.size();
                go.push_back({});
                go.back().fill(-1);
                cnt.push_back(0);
            }
            s = go[s][c];
        }
        cnt[s]++;
    }
    int states = go.size();
    vector<int> fail(states, 0), queue;
    for (int c = 0; c < 26; c++) {
        int v = go[0][c];
        if (v == -1) go[0][c] = 0;
        else queue.push_back(v);
    }
    for (size_t h = 0; h < queue.size(); h++) {
        int u = queue[h];
        cnt[u] += cnt[fail[u]];
        for (int c = 0; c < 26; c++) {
            int v = go[u][c];
            if (v == -1) go[u][c] = go[fail[u]][c];
            else { fail[v] = go[fail[u]][c]; queue.push_back(v); }
        }
    }
    int state = 0;
    long long total = 0;
    for (char ch : text) {
        state = go[state][ch - 'a'];
        total += cnt[state];
    }
    cout << total << endl;
    return 0;
}
